import {$,esc,showToast} from "./dom.js";
import {appState,placeholders,products,productSources,recentPropertyIds,rules,newRule,notificationTopics} from "./state.js";
import {renderAnnotations} from "./annotations.js";

const steps=[[1,"消息内容","主题、内容与跳转"],[2,"触发条件","触发源和提醒时间"],[3,"投递设置","送到哪里、怎么发送"]];
const product=()=>products.find(item=>item.id===appState.selectedProductId)||products[0];
const sources=()=>productSources[appState.selectedProductId]||{properties:[],countdowns:[],consumables:[]};
const productTopics=()=>notificationTopics.filter(topic=>topic.productId===appState.selectedProductId);
const currentTopic=()=>notificationTopics.find(topic=>topic.id===appState.rule.notificationTopicId);
const inTopic=()=>!!currentTopic();
const topicMembers=topicId=>rules.filter(rule=>rule.productId===appState.selectedProductId&&rule.notificationTopicId===topicId);
const topicValue=(topic,field)=>topic?.values?.["en-US"]?.[field]||"";
let pickerState={query:"",group:"all"};

function stepNav(){return `<nav class="step-nav" id="ruleStepNav" data-anchor="step-nav"><div class="step-progress"><span>规则配置</span><strong>步骤 ${appState.ruleStep} / 3</strong></div><ol class="step-list">${steps.map(([number,title,subtitle],index)=>`<li class="step-slot"><button class="step-item ${number===appState.ruleStep?"active":""} ${number<appState.ruleStep?"is-complete":""}" data-step="${number}"><span class="step-index">${number<appState.ruleStep?"✓":number}</span><span class="step-copy"><strong>${title}</strong><small>${subtitle}</small></span></button>${index<2?'<span class="step-connector"></span>':""}</li>`).join("")}</ol></nav>`}
const propertyMeta=property=>[property.id,property.type==="number"?"数值":property.type==="enum"?"枚举":"开关",property.unit].filter(Boolean).join(" · ");
const groups=()=>[...new Set(sources().properties.map(property=>property.group||"其他"))];
function matchingProperties(){const keyword=pickerState.query.trim().toLowerCase();return sources().properties.filter(property=>(pickerState.group==="all"||property.group===pickerState.group)&&(!keyword||[property.name,property.id,property.group].filter(Boolean).join(" ").toLowerCase().includes(keyword)))}
function selectProperty(property){appState.rule.propertyId=property.id;appState.rule.operator=property.operators?.[0]||"=";appState.rule.propertyValue=property.type==="enum"?property.options?.[0]||"":property.type==="boolean"?"true":property.example||""}
function pickerShell(){const all=sources().properties,rows=matchingProperties(),current=all.find(property=>property.id===appState.rule.propertyId);return `<div class="property-picker-host is-open" id="propertyPicker"><div class="property-picker-mask" data-picker-close></div><section class="property-picker"><header class="property-picker-header"><div><h3>选择设备属性</h3><p>当前产品有 ${all.length} 个属性，可用搜索或分组快速找到。</p></div><button class="icon-btn" data-picker-close>×</button></header><div class="property-picker-toolbar"><div class="property-search"><span>⌕</span><input class="el-input" data-property-query value="${esc(pickerState.query)}" placeholder="搜索属性名称或标识符"><kbd>Esc</kbd></div><div class="property-current">当前选择：<strong>${esc(current?.name||"未选择")}</strong></div></div><div class="property-picker-body"><aside class="property-group-list"><button class="property-group ${pickerState.group==="all"?"active":""}" data-property-group="all"><span>全部属性</span><b>${all.length}</b></button>${groups().map(group=>`<button class="property-group ${pickerState.group===group?"active":""}" data-property-group="${esc(group)}"><span>${esc(group)}</span><b>${all.filter(item=>item.group===group).length}</b></button>`).join("")}</aside><section class="property-results"><div class="property-results-head"><span>${pickerState.query?`“${esc(pickerState.query)}” 的结果`:pickerState.group==="all"?"全部属性":esc(pickerState.group)}</span><small>${rows.length} 个可选</small></div><div class="property-option-list">${rows.length?rows.map(property=>`<button class="property-option ${property.id===appState.rule.propertyId?"selected":""}" data-select-property="${esc(property.id)}"><span class="property-type-icon">${property.type==="number"?"#":"≡"}</span><span class="property-option-copy"><strong>${esc(property.name)}</strong><small>${esc(propertyMeta(property))}</small></span><span class="property-option-side">${property.id===appState.rule.propertyId?"已选":"选择"}</span></button>`).join(""):`<div class="property-empty"><strong>没有找到匹配属性</strong><span>试试其他名称或切换分组。</span><button class="op-link" data-picker-reset>清空搜索</button></div>`}</div></section></div><footer class="property-picker-footer"><span>属性来自当前产品的功能设计。</span><button class="el-btn" data-picker-close>取消</button></footer></section></div>`}
function closePicker(){$("#propertyPicker")?.remove()}
function rerenderPicker(){const host=$("#propertyPicker");if(!host)return;host.outerHTML=pickerShell();wirePicker()}
function wirePicker(){const host=$("#propertyPicker");if(!host)return;host.querySelectorAll("[data-picker-close]").forEach(button=>button.onclick=closePicker);host.querySelector("[data-property-query]")?.addEventListener("input",event=>{pickerState.query=event.target.value;rerenderPicker()});host.querySelectorAll("[data-property-group]").forEach(button=>button.onclick=()=>{pickerState.group=button.dataset.propertyGroup;rerenderPicker()});host.querySelector("[data-picker-reset]")?.addEventListener("click",()=>{pickerState={query:"",group:"all"};rerenderPicker()});host.querySelectorAll("[data-select-property]").forEach(button=>button.onclick=()=>{const next=sources().properties.find(property=>property.id===button.dataset.selectProperty);if(next){selectProperty(next);closePicker();rerender();showToast(`已选择：${next.name}`)}})}
function openPicker(){pickerState={query:"",group:"all"};$("#overlayRoot").insertAdjacentHTML("beforeend",pickerShell());wirePicker()}
function timeWindow(){const rule=appState.rule,cross=rule.timeStart>rule.timeEnd;return `<div class="form-section" data-anchor="trigger-time"><div class="section-title"><h3>提醒时间</h3><p>按每天的时间段发送</p></div><div class="time-range"><input class="el-input" type="time" data-rule="timeStart" value="${esc(rule.timeStart)}"><span>至</span><input class="el-input" type="time" data-rule="timeEnd" value="${esc(rule.timeEnd)}"><span class="el-tag el-tag--${cross?"warning":"info"} is-plain">${cross?"跨到次日":"当天"}</span></div><p class="form-help">只有在这个时间段内发生，才会发送提醒。</p></div>`}
function trigger(){const rule=appState.rule,source=sources(),property=source.properties.find(item=>item.id===rule.propertyId)||source.properties[0],choices=[["device","设备触发","属性满足条件时提醒"],["cloud","云端触发","计时器剩余时长到达设置值"],["consumable","耗材触发","耗材不足或耗尽时提醒"]];let detail="";
if(rule.triggerType==="device")detail=`<div class="form-grid"><div class="form-row" data-anchor="property-selector"><span class="form-label"><i class="required">*</i>设备属性</span><button class="property-select-trigger" data-open-property-picker><span class="property-select-main"><strong>${esc(property?.name||"请选择属性")}</strong><small>${esc(property?propertyMeta(property):"")}</small></span><span class="property-select-action">选择 / 更换 ›</span></button></div><label class="form-row"><span class="form-label"><i class="required">*</i>条件</span><select class="el-select" data-rule="operator">${(property?.operators||[]).map(item=>`<option ${item===rule.operator?"selected":""}>${item}</option>`).join("")}</select></label><label class="form-row full"><span class="form-label"><i class="required">*</i>条件值</span><input class="el-input" data-rule="propertyValue" value="${esc(rule.propertyValue)}"><p class="form-help">当 ${esc(property?.name||"属性")} ${esc(rule.operator)} ${esc(rule.propertyValue)}${property?.unit?` ${property.unit}`:""} 时，满足提醒条件。</p></label></div>`;
if(rule.triggerType==="cloud"){const timer=source.countdowns.find(item=>item.id===rule.cloudCountdownId)||source.countdowns[0],unit=timer?.unit||"分钟";detail=`<div class="form-grid"><label class="form-row"><span class="form-label"><i class="required">*</i>云计时器</span><select class="el-select" data-rule="cloudCountdownId">${source.countdowns.map(item=>`<option value="${item.id}" ${item.id===rule.cloudCountdownId?"selected":""}>${item.name} · 每 ${item.duration} ${item.unit}</option>`).join("")}</select></label><label class="form-row"><span class="form-label"><i class="required">*</i>剩余时长</span><div class="threshold-control"><input class="el-input" type="number" min="0" max="${timer?.duration||0}" data-rule="cloudThresholdMinutes" value="${esc(rule.cloudThresholdMinutes)}"><span>${esc(unit)}</span></div><p class="form-help">剩余时长少于或等于 ${esc(rule.cloudThresholdMinutes)} ${esc(unit)} 时提醒。</p></label></div>`}
if(rule.triggerType==="consumable")detail=`<div class="form-grid"><label class="form-row"><span class="form-label"><i class="required">*</i>耗材项</span><select class="el-select" data-rule="consumableId">${source.consumables.map(item=>`<option value="${item.id}" ${item.id===rule.consumableId?"selected":""}>${item.name}</option>`).join("")}</select></label><label class="form-row"><span class="form-label"><i class="required">*</i>触发项</span><select class="el-select" data-rule="consumableEvent"><option value="low" ${rule.consumableEvent==="low"?"selected":""}>不足</option><option value="empty" ${rule.consumableEvent==="empty"?"selected":""}>耗尽</option></select></label></div>`;
return `<div class="form-section" data-anchor="trigger-source"><div class="section-title"><h3>触发源</h3><p>通知主题决定哪些提醒汇总展示，触发源决定什么时候产生提醒。</p></div><div class="radio-row">${choices.map(([value,title,subtitle])=>`<label class="choice-card ${rule.triggerType===value?"selected":""}"><input type="radio" name="trigger" value="${value}" ${rule.triggerType===value?"checked":""}><span class="choice-copy"><strong>${title}</strong><small>${subtitle}</small></span></label>`).join("")}</div><div class="trigger-detail">${detail}</div></div>${timeWindow()}<div class="form-section" data-anchor="recipient-resolution"><div class="section-title"><h3>接收者</h3><p>系统自动处理</p></div><div class="help-alert">提醒会发给触发设备已绑定的用户。没有绑定用户时，不发送提醒。</div></div>`}
function topicEditor(){const rule=appState.rule,topic=currentTopic(),isNew=rule.notificationTopicId==="__new__",members=topic?topicMembers(topic.id):[],selector=`<div class="form-section" data-anchor="topic-selector"><div class="section-title"><h3>通知主题</h3><p>通知主题决定哪些提醒汇总展示；触发源决定什么时候产生提醒。</p></div>${topicChoice()}<button class="text-button" data-open-topic-manager>管理通知主题</button></div>`;if(!topic&&!isNew)return `${selector}<div class="form-section" data-anchor="message-editor"><div class="section-title"><h3>推送消息 · English</h3><p>这条规则独立发送</p></div>${contentFields()}</div><div class="form-section" data-anchor="jump-mode"><div class="section-title"><h3>点击后打开</h3><p>默认进入 App 消息中心</p></div>${presetSelect()}<p class="form-help">系统通知点击后也会进入这里选择的页面。</p></div>`;const title=isNew?rule.topicTitle:topicValue(topic,"title"),body=isNew?rule.topicBody:topicValue(topic,"body"),impact=members.length+(isNew?1:0),stable=placeholders.slice(0,5),special=placeholders.slice(5);return `${selector}<div class="form-section">${isNew?`<label class="form-row"><span class="form-label"><i class="required">*</i>主题名称</span><input class="el-input" data-rule="topicName" value="${esc(rule.topicName||"")}" placeholder="例如：清洗提醒"></label>`:`<div class="help-alert success">已加入「${esc(topic.name)}」· 关联 ${impact} 条规则 · 最近更新 ${esc(topic.updated)}</div>`}<div class="form-section"><div class="section-title"><h3>主题共享消息 · English</h3><p>修改后会同步影响当前主题的 ${impact} 条规则</p></div><label class="form-row full"><span class="form-label"><i class="required">*</i>Title</span><input class="el-input" data-topic-content="title" maxlength="100" value="${esc(title)}"></label><label class="form-row full"><span class="form-label"><i class="required">*</i>Body</span><textarea class="el-textarea" data-topic-content="body" maxlength="200">${esc(body)}</textarea></label><div class="placeholder-area"><div><strong>可插入内容</strong><span>主题共享文案只支持稳定的设备与用户信息</span></div><div class="placeholder-panel">${stable.map(token=>`<button class="placeholder" data-topic-placeholder="${esc(token)}">${esc(token)}</button>`).join("")}${special.map(token=>`<button class="placeholder" disabled title="这类内容只属于具体触发源，请写在提醒项中">${esc(token)}</button>`).join("")}</div></div></div><label class="form-row"><span class="form-label"><i class="required">*</i>提醒项 · English</span><input class="el-input" data-rule="itemLabel" maxlength="100" value="${esc(rule.itemLabel||"")}" placeholder="例如：Breast shields"><p class="form-help">会在消息中心汇总详情中展示，不会拼接到系统通知正文。</p></label><div class="help-alert">主题汇总固定进入消息中心详情；后续事件只更新提醒项，系统通知每天最多一次。</div></div>`}
function topicChoice(){const rule=appState.rule;return `<select class="el-select" data-topic-select><option value="" ${!rule.notificationTopicId?"selected":""}>不加入主题（独立发送）</option>${productTopics().map(topic=>`<option value="${topic.id}" ${rule.notificationTopicId===topic.id?"selected":""}>${esc(topic.name)} · ${topicMembers(topic.id).length} 条规则</option>`).join("")}<option value="__new__" ${rule.notificationTopicId==="__new__"?"selected":""}>＋ 新建通知主题</option></select>`}
function contentFields(){const rule=appState.rule;return `<label class="form-row full"><span class="form-label"><i class="required">*</i>Title</span><input class="el-input" data-content="title" maxlength="100" value="${esc(rule.title||"")}"></label><label class="form-row full"><span class="form-label"><i class="required">*</i>Body</span><textarea class="el-textarea" data-content="body" maxlength="200">${esc(rule.body||"")}</textarea></label><div class="placeholder-area" data-anchor="placeholder-panel"><div><strong>插入内容</strong><span>独立消息可用内容</span></div><div class="placeholder-panel">${placeholders.map(token=>`<button class="placeholder" data-insert-placeholder="${esc(token)}">${esc(token)}</button>`).join("")}</div></div>`}
function presetSelect(){const rule=appState.rule;return `<select class="el-select" data-preset>${product().presetLinks.map(item=>`<option value="${item.id}" ${item.id===rule.presetLinkId?"selected":""}>${item.label}</option>`).join("")}</select>`}
function basic(){return `<div class="form-section"><div class="section-title"><h3>基础信息</h3><p>规则归属当前产品</p></div><label class="form-row"><span class="form-label"><i class="required">*</i>规则名称</span><input class="el-input" data-rule="name" value="${esc(appState.rule.name)}" placeholder="例如：罩杯清洗提醒"></label></div>${topicEditor()}<div class="form-section"><div class="section-title"><h3>统一多语言</h3><p>主题文案、提醒项和独立规则内容都在产品级大表中维护</p></div><div class="help-alert success">请回到规则列表，点击「统一多语言」维护所有翻译。</div></div>`}
function delivery(){const rule=appState.rule,topic=currentTopic()||rule.notificationTopicId==="__new__",preview=`<div class="topic-preview"><strong>汇总预览</strong><ol><li><b>第一条：</b>创建一条消息中心记录。</li><li><b>同主题多来源：</b>设备、计时器或耗材后续实际发生时，补充提醒项。</li><li><b>不同主题：</b>分别生成消息，不会混在一起。</li><li><b>晚到事件：</b>更新已有详情；若当天尚未发送系统通知且该规则已开启，可发送一次。</li></ol></div>`;return `<div class="form-section" data-anchor="delivery-target"><div class="section-title"><h3>投递目标</h3><p>App 消息中心始终接收提醒</p></div><div class="radio-row"><div class="choice-card selected"><span class="choice-copy"><strong>App 消息中心 <span class="el-tag el-tag--success is-plain">必选</span></strong><small>每条提醒都会写入 App 消息中心，不能关闭</small></span></div><label class="choice-card ${rule.systemNotificationEnabled?"selected":""}"><input type="checkbox" name="system-notification" ${rule.systemNotificationEnabled?"checked":""}><span class="choice-copy"><strong>同时发送系统通知</strong><small>${topic?"同主题同设备每天最多一次":"可选发送到手机通知栏"}</small></span></label></div></div>${topic?`<div class="form-section" data-anchor="topic-summary"><div class="section-title"><h3>主题汇总</h3><p>固定投递方式</p></div><div class="help-alert success">同设备、同主题、同自然日共用一条消息中心记录。后续事件更新提醒项；若任一实际触发规则开启系统通知，当天最多发送一次。</div>${preview}</div>`:`<div class="form-section" data-anchor="delivery-mode"><div class="section-title"><h3>发送方式</h3><p>控制同一条规则重复提醒的方式</p></div><div class="radio-row"><label class="choice-card ${rule.reminderMode!=="discard"?"selected":""}"><input type="radio" name="mode" value="each" ${rule.reminderMode!=="discard"?"checked":""}><span class="choice-copy"><strong>逐条发送</strong><small>每次满足条件都发送</small></span></label><label class="choice-card ${rule.reminderMode==="discard"?"selected":""}"><input type="radio" name="mode" value="discard" ${rule.reminderMode==="discard"?"checked":""}><span class="choice-copy"><strong>仅发送首条</strong><small>一段时间内只发第一次提醒</small></span></label></div>${rule.reminderMode==="discard"?`<label class="form-row interval-field" data-anchor="min-interval"><span class="form-label"><i class="required">*</i>最小发送间隔</span><div class="threshold-control"><input class="el-input" type="number" min="5" max="10080" data-rule="minIntervalMinutes" value="${esc(rule.minIntervalMinutes)}"><span>分钟</span></div></label>`:""}</div>`}<div class="form-section" data-anchor="validation"><div class="section-title"><h3>保存检查</h3><p>确认主要配置是否完整</p></div>${validation()}</div>`}
function validation(){const rule=appState.rule,topic=currentTopic(),messageOk=inTopic()?!!topicValue(topic,"title").trim()&&!!topicValue(topic,"body").trim()&&!!rule.itemLabel.trim():rule.notificationTopicId==="__new__"?!!rule.topicName?.trim()&&!!rule.topicTitle?.trim()&&!!rule.topicBody?.trim()&&!!rule.itemLabel.trim():!!rule.title?.trim()&&!!rule.body?.trim(),intervalOk=inTopic()||rule.notificationTopicId==="__new__"||rule.reminderMode!=="discard"||(+rule.minIntervalMinutes>=5&&+rule.minIntervalMinutes<=10080),checks=[[!!rule.name.trim(),"规则名称"],[messageOk,inTopic()?"主题文案与提醒项":"English 内容"],[!!rule.timeStart&&!!rule.timeEnd&&rule.timeStart!==rule.timeEnd,"提醒时间"],[intervalOk,"最小发送间隔"]];return `<div class="validation-list">${checks.map(([ok,text])=>`<div class="validation-item ${ok?"":"validation-fail"}"><span>${ok?"✓":"!"} ${text}</span><span class="el-tag el-tag--${ok?"success":"danger"} is-plain">${ok?"通过":"请完善"}</span></div>`).join("")}</div>`}
function content(){return appState.ruleStep===1?basic():appState.ruleStep===2?trigger():delivery()}
function shell(){return `<div class="drawer-host is-open" id="ruleDrawer"><div class="drawer-mask" data-close></div><aside class="drawer"><header class="drawer-header"><div class="drawer-title"><h2>${appState.editingRule?"编辑":"新建"}推送规则</h2><p>${esc(product().name)} · 消息推送</p></div><button class="icon-btn" data-close>×</button></header><div class="drawer-main">${stepNav()}<div class="drawer-body"><section class="drawer-content" id="ruleStepContent">${content()}</section></div></div><footer class="drawer-footer"><span class="save-hint">保存后按当前产品生效</span><div class="footer-actions"><button class="el-btn" data-draft>保存草稿</button><button class="el-btn" data-prev ${appState.ruleStep===1?"disabled":""}>上一步</button>${appState.ruleStep<3?'<button class="el-btn el-btn--primary" data-next>下一步</button>':'<button class="el-btn el-btn--primary" data-publish>保存并启用</button>'}</div></footer></aside></div>`}
function rerender(){const host=$("#ruleDrawer");if(!host)return;host.outerHTML=shell();wire();renderAnnotations(`rule${appState.ruleStep}`,`规则配置 · 步骤 ${appState.ruleStep}/3`)}
function triggerLabel(){const rule=appState.rule;if(rule.triggerType==="device"){const property=sources().properties.find(item=>item.id===rule.propertyId);return `设备：${property?.name||"属性"} ${rule.operator} ${rule.propertyValue}${property?.unit?` ${property.unit}`:""}`}if(rule.triggerType==="cloud"){const timer=sources().countdowns.find(item=>item.id===rule.cloudCountdownId);return `云端：${timer?.name||"计时器"} ≤ ${rule.cloudThresholdMinutes} ${timer?.unit||"分钟"}`}const item=sources().consumables.find(value=>value.id===rule.consumableId);return `耗材：${item?.name||"耗材"}${rule.consumableEvent==="empty"?"耗尽":"不足"}`}
function strategyLabel(){const rule=appState.rule,topic=currentTopic();if(topic)return `${topic.name} · 主题汇总`;if(rule.notificationTopicId==="__new__")return `${rule.topicName||"新主题"} · 主题汇总`;return `${rule.reminderMode==="discard"?`仅发送首条 · ${rule.minIntervalMinutes} 分钟`:"逐条发送"} · 消息中心${rule.systemNotificationEnabled?" + 系统通知":""}`}
function persistTopic(){const rule=appState.rule;if(rule.notificationTopicId==="__new__"){const id=`topic-${Date.now()}`,topic={id,productId:appState.selectedProductId,name:rule.topicName,revision:1,updated:"刚刚",values:{"en-US":{title:rule.topicTitle,body:rule.topicBody}}};notificationTopics.push(topic);rule.notificationTopicId=id;rule.topicRevision=1;return}const topic=currentTopic();if(topic&&rule.topicRevision&&rule.topicRevision!==topic.revision)throw new Error("主题已被其他人修改，请重新加载后再保存");if(topic&&rule.topicDirty){topic.values["en-US"]={title:rule.topicTitle,body:rule.topicBody};topic.revision++;topic.updated="刚刚";rule.topicRevision=topic.revision}}
function save(status){try{persistTopic()}catch(error){showToast(error.message,"error");return}const rule=appState.rule,topic=currentTopic(),row={...rule,id:rule.id||`R-${2050+rules.length}`,productId:appState.selectedProductId,name:rule.name,product:product().name,trigger:triggerLabel(),title:topic?topicValue(topic,"title"):rule.title,languages:"1",strategy:strategyLabel(),status,updated:"2026-08-13 16:30",topicRevision:topic?.revision||0};const existing=rules.find(item=>item.id===rule.id);if(existing)Object.assign(existing,row);else rules.unshift(row);window.dispatchEvent(new Event("message-push:rule-changed"));showToast(status==="启用"?"规则已保存并启用":"规则草稿已保存");closeRuleDrawer()}
function insertToken(input,token){if(!input)return;const start=input.selectionStart??input.value.length,end=input.selectionEnd??input.value.length;input.value=`${input.value.slice(0,start)}${token}${input.value.slice(end)}`;input.focus();input.selectionStart=input.selectionEnd=start+token.length;input.dispatchEvent(new Event("input",{bubbles:true}))}
function wire(){const host=$("#ruleDrawer");host.querySelectorAll("[data-close]").forEach(item=>item.onclick=closeRuleDrawer);host.querySelectorAll("[data-step]").forEach(item=>item.onclick=()=>{appState.ruleStep=+item.dataset.step;rerender()});host.querySelectorAll("[data-rule]").forEach(item=>item.onchange=()=>{appState.rule[item.dataset.rule]=item.value;rerender()});host.querySelector("[data-topic-select]")?.addEventListener("change",event=>{const topic=notificationTopics.find(item=>item.id===event.target.value);appState.rule.notificationTopicId=event.target.value;appState.rule.topicRevision=topic?.revision||0;appState.rule.topicTitle=topicValue(topic,"title");appState.rule.topicBody=topicValue(topic,"body");appState.rule.topicDirty=false;rerender()});host.querySelectorAll("[data-topic-content]").forEach(input=>{input.onfocus=()=>appState.activeContentField=`topic-${input.dataset.topicContent}`;input.oninput=()=>{appState.rule[`topic${input.dataset.topicContent[0].toUpperCase()}${input.dataset.topicContent.slice(1)}`]=input.value;appState.rule.topicDirty=true}});host.querySelectorAll("[data-content]").forEach(input=>{input.onfocus=()=>appState.activeContentField=`rule-${input.dataset.content}`;input.oninput=()=>{appState.rule[input.dataset.content]=input.value}});host.querySelectorAll("[data-insert-placeholder]").forEach(button=>button.onclick=()=>{const field=(appState.activeContentField||"rule-title").split("-")[1];insertToken(host.querySelector(`[data-content="${field}"]`),button.dataset.insertPlaceholder)});host.querySelectorAll("[data-topic-placeholder]").forEach(button=>button.onclick=()=>{const field=(appState.activeContentField||"topic-title").split("-")[1];insertToken(host.querySelector(`[data-topic-content="${field}"]`),button.dataset.topicPlaceholder)});host.querySelector("[data-open-topic-manager]")?.addEventListener("click",()=>{const topic=productTopics()[0];showToast(topic?`主题「${topic.name}」正在被 ${topicMembers(topic.id).length} 条规则引用，不能删除；可在主题名称处重命名。`:"当前产品还没有通知主题")});host.querySelector("[data-open-property-picker]")?.addEventListener("click",openPicker);host.querySelectorAll('input[name="trigger"]').forEach(input=>input.onchange=()=>{appState.rule.triggerType=input.value;rerender()});host.querySelectorAll('input[name="mode"]').forEach(input=>input.onchange=()=>{appState.rule.reminderMode=input.value;rerender()});host.querySelector('input[name="system-notification"]')?.addEventListener("change",event=>{appState.rule.systemNotificationEnabled=event.target.checked;rerender()});host.querySelector("[data-preset]")?.addEventListener("change",event=>{appState.rule.presetLinkId=event.target.value});host.querySelector("[data-prev]")?.addEventListener("click",()=>{appState.ruleStep--;rerender()});host.querySelector("[data-next]")?.addEventListener("click",()=>{appState.ruleStep++;rerender()});host.querySelector("[data-draft]")?.addEventListener("click",()=>save("草稿"));host.querySelector("[data-publish]")?.addEventListener("click",()=>{if(host.querySelectorAll(".validation-fail").length){showToast("请先补全需要完善的内容","error");return}if(appState.rule.topicDirty&&currentTopic()&&topicMembers(currentTopic().id).length>1){if(!window.confirm(`共享文案将同步影响 ${topicMembers(currentTopic().id).length} 条规则，是否继续？`))return}save("启用")})}
export function openRuleDrawer({edit=false}={}){appState.editingRule=edit;appState.ruleStep=1;$("#overlayRoot").innerHTML=shell();wire();renderAnnotations("rule1","规则配置 · 步骤 1/3")}
export function closeRuleDrawer(){closePicker();$("#ruleDrawer")?.remove();renderAnnotations("rules","推送规则列表")}
export function resetRuleDraft(){appState.rule={...newRule(),productId:appState.selectedProductId};appState.activeContentField="title"}
